-- schema.sql
CREATE EXTENSION IF NOT EXISTS vector;

CREATE TABLE IF NOT EXISTS chunks (
  id        BIGSERIAL PRIMARY KEY,
  doc_id    TEXT NOT NULL,
  secao     TEXT NOT NULL,
  texto     TEXT NOT NULL,
  embedding VECTOR(384) NOT NULL,
  tsv       TSVECTOR GENERATED ALWAYS AS (to_tsvector('portuguese', texto)) STORED
);

CREATE INDEX IF NOT EXISTS chunks_embedding_idx
  ON chunks USING hnsw (embedding vector_cosine_ops);

CREATE INDEX IF NOT EXISTS chunks_tsv_idx
  ON chunks USING gin (tsv);

# ingest.py
import pathlib
import psycopg
from pgvector.psycopg import register_vector
from sentence_transformers import SentenceTransformer

MODELO = SentenceTransformer("sentence-transformers/paraphrase-multilingual-MiniLM-L12-v2")
MAX_PALAVRAS, OVERLAP = 180, 30

def secoes(md: str):
    titulo, linhas = "Introdução", []
    for linha in md.splitlines():
        if linha.startswith("## "):
            if linhas:
                yield titulo, "\n".join(linhas)
            titulo, linhas = linha[3:].strip(), []
        else:
            linhas.append(linha)
    if linhas:
        yield titulo, "\n".join(linhas)

def chunks(doc_id: str, md: str):
    for titulo, texto in secoes(md):
        palavras = texto.split()
        inicio = 0
        while inicio < len(palavras):
            pedaco = " ".join(palavras[inicio:inicio + MAX_PALAVRAS])
            yield doc_id, titulo, f"{titulo}\n{pedaco}"
            inicio += MAX_PALAVRAS - OVERLAP

def main():
    registros = []
    for arquivo in pathlib.Path("docs").glob("*.md"):
        registros.extend(chunks(arquivo.stem, arquivo.read_text(encoding="utf-8")))

    vetores = MODELO.encode([r[2] for r in registros], normalize_embeddings=True)

    with psycopg.connect("postgresql://rag:rag@localhost:5432/rag") as conn:
        register_vector(conn)
        conn.execute("TRUNCATE chunks")
        with conn.cursor() as cur:
            cur.executemany(
                "INSERT INTO chunks (doc_id, secao, texto, embedding) VALUES (%s, %s, %s, %s)",
                [(d, s, t, v) for (d, s, t), v in zip(registros, vetores)],
            )

    print(f"{len(registros)} chunks indexados")

if __name__ == "__main__":
    main()
